import {tokenRoadmap} from './lessons.mjs';
import {wagerRulesHTML} from './wager-rules.mjs';
import {LEVELS,wealthBenchmark} from './levels.mjs';
const money=n=>'$'+n.toLocaleString('en-US');
export function quickGuide(lang){const vi=lang==='vi';return `<details><summary>${vi?'Mới chơi? Đọc luật nhanh trong 60 giây':'New here? Read the 60-second rules'}</summary>${tokenRoadmap(lang)}<p>${vi?'Mốc thắng: Dễ 60 · Trung bình 70 · Khó 75/100; đủ 12 tháng và không thiếu thanh toán.':'Clear targets: Easy 60 · Medium 70 · Hard 75/100; finish 12 months with no missed payment.'}</p><ol>${(vi?['Mục tiêu: qua đủ 12 tháng, trả hết nghĩa vụ đến hạn và đạt điểm mục tiêu của cấp. Có nhiều tiền nhất chưa chắc thắng.','Trước lượt: chia tiền cho dự phòng, đầu tư hoặc giữ tiền mặt. Lượt gieo đầu luôn là Cơ hội; sau đó gieo một nhóm sự kiện và hai ô khác nhau cùng nhóm; so sánh vốn cần, khả năng bán và nợ trả góp trước khi chọn vị trí; tình huống đầy đủ mở sau khi chọn. Chỉ ô dừng chân có sự kiện.','Sau khi chọn: nhận lương, cập nhật lời/lỗ và tiền phân phối danh mục hằng tháng, trả sinh hoạt, chi phí theo cấp và trả góp. Sau đó xử lý tình huống của ô. Chi tiêu tự chọn có thể bỏ qua.','Điểm /100: tài sản 40, dự phòng 35, thanh khoản 15, kiến thức 10. Bắt đầu 80 HUB. Solo: Dễ miễn phí, Trung bình cam kết 40, Khó 80. Duet/nhóm cược 10/40/80; phải qua Hub mới được xét thắng cược. Thắng hoàn cam kết và có thưởng; thua hoặc bỏ chặng mất cam kết.']:['Goal: finish 12 months, meet all due payments and reach the level’s score target. Having the most money alone does not guarantee a win.','Before a turn: allocate reserves, invest or keep cash. The first draw always offers Opportunity; later draws select one category and two spaces in it; compare capital needs, liquidity and installments before choosing; the full card opens afterward. Only the landing space triggers an event.','After choosing: receive salary, apply monthly portfolio valuation changes and cash distributions, pay living costs, level pressure and installments; then handle the landing event. Optional purchases can be declined.','Score /100: wealth 40, reserves 35, liquidity 15, knowledge 10. Start with 80 HUB. Solo: Easy is free; Medium commits 40, Hard 80. Duet/group stakes are 10/40/80; clear Hub first to qualify for a wager win. Win to reclaim it plus rewards; losing or abandoning forfeits it.']).map(x=>`<li>${x}</li>`).join('')}</ol><a href="./rules.html">${vi?'Đọc giới thiệu, luật đầy đủ & ví dụ →':'Read the introduction, full rules & examples →'}</a></details>`;}
export function guideHTML(lang,state={difficulty:'easy'}){const vi=lang==='vi',pick=(a,b)=>vi?a:b;
const sections=[
[pick('Cảm hứng từ Cờ Tỷ Phú','Inspired by Monopoly'),pick('Cờ Tỷ Phú (Monopoly) là trò chơi bàn cờ về mua bán, đầu tư và kinh doanh bất động sản có nguồn gốc từ Mỹ. Money Lab Hub lấy cảm hứng từ cách di chuyển quanh bàn cờ và đưa ra quyết định tài chính, rồi phát triển luật riêng để bạn tập quản lý tiền trước khi dùng tiền thật. Đây là dự án độc lập, không phải phiên bản chính thức hay sản phẩm được Hasbro bảo trợ.','Monopoly is a property trading board game originating in the United States. Money Lab Hub draws inspiration from moving around a board and making financial decisions, with its own rules for practicing money management before using real money. This independent project is not an official Monopoly edition or endorsed by Hasbro.')],
[pick('1. Thắng bằng cách nào?','1. How do you win?'),pick('Một chặng kéo dài 12 tháng. Để thắng, bạn phải hoàn thành đủ 12 tháng, không có khoản bắt buộc chưa thanh toán, và đạt tối thiểu 60 điểm ở Dễ, 70 ở Trung bình hoặc 75 ở Khó. Hết 12 tháng nhưng thiếu điểm vẫn là chưa thắng. Không đủ tiền trả nghĩa vụ dù đã dùng hết tiền thanh khoản thì chặng kết thúc sớm.','A stage lasts 12 months. Win by completing all 12, leaving no required payment unpaid, and scoring at least 60 on Easy, 70 on Medium or 75 on Hard. Completing the year below target is not a win. A required payment that cannot be covered by available liquid funds ends the stage early.')],
[pick('2. Một lượt diễn ra như thế nào?','2. What happens in a turn?'),pick('① Trước khi gieo, chuyển tiền giữa tiền mặt và dự phòng, mua quỹ ML-100 hoặc bán tài sản thanh khoản nếu muốn. ② Lượt gieo đầu tiên luôn mở Cơ hội để cân nhắc đầu tư sớm (vẫn áp dụng thu–chi tháng 1). Những lượt sau xác định một nhóm sự kiện, rồi mở hai ô khác nhau cùng nhóm, ví dụ Cơ hội ô 2 hoặc ô 11. Chọn một ô, không chọn nhóm khác; thẻ cụ thể chưa được tiết lộ. Đây là lượt rút điểm đến, không phải cộng số bước hai xúc xắc. ③ Chọn xong mới sang tháng mới: nhận lương, cập nhật giá trị từng khoản đầu tư và tiền phân phối (nếu có), rồi trả sinh hoạt và chi phí bắt buộc theo cấp, rồi trả góp đến hạn. ④ Nếu còn khả năng thanh toán, xử lý sự kiện tại ô đến. ⑤ Xem kết quả, điều chỉnh vốn và chơi tháng kế tiếp. Chỉ ô dừng chân được kích hoạt; đi qua Khởi đầu không có thưởng.','① Before rolling, move cash into or out of reserves, buy the fictional ML-100 fund, or sell liquid investments. ② The first draw always offers Opportunity for an early investment decision (normal month-one income and costs still apply). Later draws select one event category and two different spaces in it, e.g. Opportunity at space 2 or 11. Choose one without seeing its card. This is a destination draw, not the sum of two movement dice. ③ Choosing advances one month: collect salary, update every existing investment and any cash distribution, then pay living costs and mandatory level charges, then due installments. ④ If still solvent, resolve the landing event. ⑤ Review, adjust funds and continue. Only landing triggers a space; passing Start gives no bonus.')],
[pick('3. May rủi và quyết định của bạn','3. Chance and your decisions'),pick('Bạn biết loại ô trước khi chọn, nhưng chưa biết thẻ cụ thể. Hai lựa chọn luôn cùng nhóm sự kiện; mỗi vị trí có thể mở một thẻ khác nhau, không có đường đi nào đảm bảo thắng. Hai điểm đến được giữ khi tải lại trang, không thể gieo lại miễn phí. Bạn kiểm soát đường đi, mức dự phòng, quy mô đầu tư, nợ trả góp, quyết định mua/bỏ qua và câu trả lời. Thẻ bất ngờ và thị trường vẫn có yếu tố xác suất: bản này giảm việc bị ép đi một đường, chưa loại bỏ may rủi và chưa phải hệ thống xếp hạng kỹ năng chuẩn hóa.','You see each landing type before choosing, but not its specific card. Both options always share the same category; each space may reveal a different card, no route guarantees a win. Reloading preserves the locked destinations. You control your route, reserves, investment size, installment debt, optional purchases and quiz answers. Events and markets still involve chance: this version gives more agency but does not eliminate luck or provide a standardized skill ranking.')],
[pick('4. Các ô trên bàn cờ','4. Board spaces'),pick('Cơ hội: xem một khoản đầu tư cụ thể rồi mua hoặc bỏ qua. Bất ngờ: hóa đơn thiết yếu, món tự thưởng có thể từ chối, hoặc khoản thu một lần như quà gia đình, thừa kế, giải thưởng hay bốc thăm miễn phí. Không mua vé số và không mất HUB để nhận may mắn. Kiến thức: chặng mới có 2 cơ hội trả lời nếu hoàn thành đủ 12 tháng và còn thanh toán được. Tối đa 2 lần; nếu chưa đủ, lượt cuối được dành cho Kiến thức. Khi hết ngân hàng câu hỏi mới bắt đầu vòng câu hỏi tiếp theo. Chọn đáp án, tích lũy điểm kiến thức; trả lời đúng không sinh tiền. Thị trường: cú sốc lớn áp dụng thêm sau cập nhật thường tháng cho từng nhóm tài sản đang giữ, không tác động trực tiếp đến tiền mặt/dự phòng. Thu nhập thêm: một công việc cụ thể như thiết kế freelance, dạy kèm, dịch thuật, bán hàng online hoặc gian hàng cuối tuần, nhận ròng $250–$700 sau chi phí. Khởi đầu là vị trí xuất phát; lượt rút mới chỉ mở các nhóm có ít nhất hai ô. Ván lưu cũ vẫn nhận $300 nếu dừng Khởi đầu theo luật cũ. Đây là tiền USD giả lập.','Opportunity: inspect a specific investment and buy or pass. Unexpected: a required bill, an optional treat, or a one-off family gift, inheritance, prize or free draw. No lottery tickets are bought and no HUB is paid to receive a windfall. Knowledge: new solvent 12-month completions receive two answer opportunities, at most two visits. Remaining slots are reserved near year-end if needed. The question bank cycles only after exhaustion. Answer for the knowledge score, not cash. Market: apply an additional large category-specific shock after the regular monthly update, not directly to cash or reserves. Extra income: a specific completed job such as freelance design, tutoring, translation, online sales or a weekend stall, paying $250–$700 net of costs. Start marks the starting position; new draws use categories with at least two spaces. Legacy saved routes still receive $300 when landing on Start. All USD amounts are simulated.')],
[pick('5. Tiền, tài sản, nợ và chi tiêu','5. Money, assets, debt and spending'),pick('Tài sản ròng = tiền mặt + dự phòng + giá trị đầu tư − nợ còn lại. Mua tài sản theo giá mô hình chỉ chuyển loại tài sản, không tự tạo lợi nhuận. Chi sinh hoạt và trả góp dùng tiền mặt trước, rồi dự phòng; hóa đơn bất ngờ dùng dự phòng trước, rồi tiền mặt. Thiếu tiền sẽ tự bán tài sản thanh khoản và trừ điểm thanh khoản. Vốn kinh doanh và bất động sản khóa bán suốt chặng. Ví dụ phần bất động sản $4.500: trả trước $2.700, nợ $1.800 và trả $300/tháng trong 6 lượt tiếp theo. Mỗi tháng đều cập nhật định giá, kể cả không vào ô Thị trường. Bất động sản và vốn kinh doanh có thể chia tiền mặt giả lập 0–1,5% giá trị đầu tháng; có tháng không chia, giá trị vẫn có thể giảm. Cổ phiếu, coin và quỹ chỉ có thay đổi định giá. Chưa mô phỏng lãi vay, thuế và cổ tức cổ phiếu. Mua trong tháng chỉ bắt đầu nhận cập nhật từ tháng kế tiếp. Chi iPhone/xe/du lịch chỉ tăng điểm trải nghiệm riêng, không tăng điểm tài chính, không có giá trị bán lại trong mô hình.','Net worth = cash + reserves + investments − outstanding debt. Buying at modeled value changes asset allocation without creating profit. Living costs and installments use cash first, then reserves; unexpected bills use reserves first, then cash. A remaining shortage forces liquid investment sales and reduces liquidity points. Business and property capital cannot be sold during a stage. Example: a $4,500 property share costs $2,700 down and creates $1,800 debt, repaid at $300 over the next six turns. Valuations update every month, even without a Market landing. Property and business may distribute fictional cash of 0–1.5% of opening value; some months pay nothing and capital value can still fall. Stocks, coins and funds only receive valuation changes. Interest, taxes and stock dividends are not modeled. New purchases start updating the following month. Phones, cars and travel add separate enjoyment points, not financial score, with no modeled resale value.')],
[pick('6. Điểm /100 được tính thế nào?','6. How is the /100 score calculated?'),pick('Tài sản /40: tài sản ròng ÷ mốc tài sản của cấp × 40, làm tròn và giới hạn 0–40. Dự phòng /35: dự phòng ÷ (3 × sinh hoạt tháng cơ bản) × 35, làm tròn và tối đa 35. Thanh khoản /15: bắt đầu 15, trừ 5 mỗi lần bị buộc bán; còn khoản chưa trả thì mất toàn bộ phần này. Kiến thức /10: tỷ lệ đáp án đúng × 10, làm tròn; chưa gặp câu nào thì phần này là 0. Tổng bốn phần là điểm cuối chặng. Mốc tài sản = số lớn hơn giữa vốn ban đầu và vốn ban đầu + 12 × (lương cơ bản − sinh hoạt cơ bản) − tổng giảm lương theo lịch. Mốc không cộng thưởng ô hay trừ chi phí bất ngờ.','Wealth /40: net worth ÷ the level benchmark × 40, rounded and capped at 0–40. Reserves /35: reserves ÷ (3 × base monthly living costs) × 35, rounded and capped at 35. Liquidity /15: start at 15, lose 5 per forced sale; any unpaid amount removes this component. Knowledge /10: correct-answer rate × 10, rounded; zero questions means zero here. Add the four components. The wealth benchmark is the greater of starting capital and starting capital + 12 × (base salary − base living costs) − scheduled income cuts. It excludes tile bonuses and unexpected expenses.')],
[pick('7. HUB: vào chặng, thắng, thua và chơi tiếp','7. HUB: entry, wins, losses and continuation'),pick('Hồ sơ mới được cấp 80 HUB một lần. Dễ vào miễn phí; Trung bình cam kết 40 HUB; Khó cam kết 80 HUB. Bản 22 điều chỉnh cấp Khó cho chặng mới: giảm thu nhập $300 ở tháng 3/6/9/12; chi thêm $500 ở tháng 1 và $250 ở tháng 3/5/7/9/11. Mốc thắng vẫn 75. Chặng cũ giữ mức chi đã có. Thắng Dễ mở Trung bình; thắng Trung bình mở Khó, đồng thời phải đủ HUB mới vào được. Thắng hoàn lại cam kết và nhận thưởng cơ bản: Dễ 12, Trung bình 28, Khó 60 HUB; mỗi 5 điểm trọn vẹn vượt mục tiêu được thêm tương ứng 2 / 3 / 4 HUB. Thua hoặc bỏ chặng mất cam kết, không có thưởng. Mỗi lần thắng chặng mới đều nhận thưởng, một kết quả chỉ nhận một lần. Hết HUB vẫn được về Dễ. Bấm Tiếp tục để vào chặng mới: giữ ngân hàng HUB, mở khóa và lịch sử, bắt đầu ngân sách USD riêng của chặng mới.','A new profile receives 80 HUB once. Easy is free; Medium commits 40 HUB and Hard 80. Version 22 changes new Hard stages to $300 income cuts in months 3/6/9/12, $500 extra cost in month 1 and $250 in months 3/5/7/9/11. The target remains 75. Existing stages retain their old costs. Win Easy to unlock Medium, then Medium to unlock Hard; you must also afford the commitment. A win returns it plus a base reward of 12 / 28 / 60 HUB; every full 5 points above target adds 2 / 3 / 4 HUB respectively. Losing or abandoning forfeits the commitment with no reward. Each new winning stage pays once. Easy remains free at zero HUB. Continue directly to another stage: HUB, unlocks and history persist; the stage’s simulated USD budget starts afresh.')],
[pick('8. Duet / Nhóm: thắng Hub trước, thắng cược sau','8. Duet / Group: clear Hub first, compete second'),pick('Có phòng online 2–6 người khác thiết bị tại mục Duet / Nhóm online; chế độ luân phiên cùng thiết bị vẫn được giữ. Mỗi ghế có hồ sơ HUB riêng, tách solo; mọi người phải mở khóa cùng cấp và đủ cược. Mỗi tháng dùng chung hai lựa chọn xúc xắc và hạt giống rút thẻ. Cùng đường và lịch sử rút thẻ cho cùng tình huống. Cược Dễ 10, Trung bình 40, Khó 80 HUB/người; không thu thêm cam kết Hub trùng lặp. Thưởng chặng Hub vẫn tính bình thường và độc lập: qua đủ 12 tháng, không thiếu thanh toán, đạt điểm mục tiêu. Người trượt Hub tự động thua cược dù điểm cao nhất. Có tối đa ⌈N/2⌉ suất thắng cược, xếp những người qua Hub theo điểm, rồi tài sản ròng, rồi dự phòng. Ít người đủ điều kiện thì để trống suất; không đưa người trượt Hub lên thay. Người thắng được hoàn cược, nhận thưởng Hub nếu đạt và chia quỹ cược. Người qua Hub nhưng ngoài suất thắng cược vẫn nhận thưởng Hub, nhưng mất cược. Tổng cược của người thua: 50% vào công quỹ, 50% chia cho người thắng theo tỷ lệ điểm. HUB nguyên dùng phương pháp phần dư lớn nhất. Ví dụ 3 người Trung bình, cược 40, hai người thắng 80/70 điểm: hoàn mỗi người 40 và chia thêm 11/9 HUB; công quỹ nhận 20, người thua mất 40. Nếu đồng hạng hoàn toàn ở ranh giới suất thắng, các ghế đồng hạng hòa cược và hoàn cược; thưởng Hub không đổi. Nếu không có người thắng cược, 50% vào công quỹ, 50% giữ ở quỹ thưởng chờ cho trận sau có người thắng. Bỏ trận: mọi ghế chưa hoàn thành trượt Hub, thua cược; ghế đã hoàn thành giữ điều kiện xét thưởng. Công quỹ cùng thiết bị lưu trên trình duyệt; phòng online dùng sổ HUB giả lập chung trên máy chủ và quỹ thưởng chờ theo phòng. Đây không phải tài sản của dự án trên blockchain.','Online rooms support 2–6 people on separate devices; shared-device play remains available. Each seat has a separate profile from solo; all players must unlock the same level and afford its stake. Monthly destination draws, portfolio conditions and card seeds are shared; identical routes and card histories give identical events. Stake per player: Easy 10, Medium 40, Hard 80 HUB, without an additional Hub commitment. Normal Hub stage rewards remain independent: finish 12 months, meet required payments and reach the target score. A Hub failure automatically loses the wager even with the highest score. Up to ⌈N/2⌉ wager-winning seats are filled from Hub clears only, ranked by score, net worth, then reserves. Unfilled slots remain empty. Wager winners reclaim their own stakes, retain Hub rewards and share the wager pool. A Hub clear outside the winning seats still earns its normal Hub reward but forfeits its stake. Half of all losing stakes goes to the treasury and half pays winners proportionally to score, using largest remainders for whole HUB. Example: three Medium players stake 40 each; 80/70-point winners reclaim 40 each and receive 11/9 extra HUB. The treasury receives 20 and the loser forfeits 40. A complete tie at the winning cutoff refunds the tied seats; Hub rewards are unchanged. If nobody wins the wager, half goes to the treasury and half carries to the next match with winners. Abandoning fails every unfinished seat; completed clears retain eligibility. Local treasury is browser-local; online rooms use a shared fictional server ledger with per-room prize carry. These are not blockchain project assets.')],
[pick('9. Ví dụ dễ hiểu','9. A worked example'),pick('Tháng 1 cấp Dễ: từ $7.000 tiền mặt, $3.000 dự phòng, bạn chuyển $500 vào dự phòng → còn $6.500 tiền mặt, $3.500 dự phòng. Lượt gieo mở hai ô Cơ hội; chọn một vị trí. Nhận $1.800 lương và trả $1.400 sinh hoạt → có $6.900 tiền mặt. Bạn có thể mua hoặc bỏ qua cơ hội, không bắt buộc mua. Cuối chặng nếu đạt 60 điểm, hoàn thành đủ tháng và không thiếu thanh toán: Dễ thắng, nhận 12 HUB, từ 80 thành 92 HUB.','Easy month 1: start with $7,000 cash and $3,000 reserves. Move $500 to reserves → $6,500 cash and $3,500 reserves. Draw two Opportunity spaces and choose one. Collect $1,800 salary and pay $1,400 living costs → $6,900 cash. Buy or decline the opportunity. A solvent 12-month Easy completion at 60 points earns 12 HUB, taking an untouched starting balance from 80 to 92.')],
[pick('10. Ví Web3, TapeOut và lưu tiến độ','10. Web3, TapeOut and saving'),pick('HUB là token giả lập trong trò chơi: không phải token đã phát hành, không đổi ra OKB hoặc tiền thật. Chơi không yêu cầu nạp OKB hay ký giao dịch ví. Game đọc mạch TapeOut #48 trên X Layer để kiểm tra tín hiệu tạm khóa đầu tư mới khi dự phòng cạn và chi phí bắt buộc vượt tiền thanh khoản trước chi trả. Nếu không đọc được mạch, quyết định chưa được áp dụng và bạn cần thử lại. Tiến độ lưu trên trình duyệt này, chưa đồng bộ tài khoản; xóa dữ liệu hoặc đổi thiết bị có thể mất tiến độ. Muốn chơi lại hoàn toàn: bấm “Xóa toàn bộ tiến độ” ở đầu trang rồi xác nhận. Toàn bộ solo và duet trên trình duyệt này bị xóa, hồ sơ về 80 HUB và cấp Dễ. “Chặng mới” chỉ đổi chặng và giữ HUB/lịch sử. Giá tài sản và tình huống đều giả định, không phải khuyến nghị đầu tư.','HUB is a simulated in-game token: it is not an issued token and cannot be redeemed for OKB or real money. Playing requires no OKB deposit or wallet transaction signature. The game reads TapeOut circuit #48 on X Layer for a gate that pauses new investment when reserves are exhausted and required costs exceed pre-payment liquid funds. If the circuit read fails, your decision is not applied; retry it. Progress is saved in this browser without account syncing; clearing data or changing devices can lose progress. To start completely over, use “Reset all progress” at the top and confirm. All solo and duet/group progress in this browser is deleted, returning profiles to 80 HUB and Easy. “New stage” only changes the stage and keeps HUB/history. Prices and scenarios are fictional, not investment advice.')]
];
return `<p class="eyebrow">MONEY LAB HUB / GUIDE</p><h1>${pick('Giới thiệu & Luật chơi','About & Rules')}</h1><p class="guide-lead">${pick('Tập quản lý tiền trước khi dùng tiền thật. Chọn đường đi, cân đối dòng tiền và giữ khả năng tồn tại trong 12 tháng.','Practice with money before it is real. Choose your route, balance cash flow and stay solvent for 12 months.')}</p>${quickGuide(lang)}<section><h2>${pick('Biểu đồ tài chính & nhạc nền','Financial dashboard & music')}</h2><p>${pick('Bảng điều khiển xuất hiện từ đầu chặng và cập nhật sau mỗi quyết định: cơ cấu vốn, tiền dùng ngay, vốn khóa, nợ, dự phòng theo số tháng và nghĩa vụ đã biết tháng tới. Đường biểu đồ nối các mốc lưu thực tế; không phải giá thị trường trực tiếp. Dự tính không cộng thu nhập bất thường và không trừ hóa đơn bất ngờ, nên số dư dương không đảm bảo an toàn. Nhạc nền là giai điệu tạo riêng; bấm Bật nhạc nền để nghe, chỉnh âm lượng hoặc tắt bất kỳ lúc nào. Chuyển sang tab khác sẽ tạm dừng.','The dashboard appears before the stage starts and updates after each decision: capital mix, available money, locked capital, debt, reserve months and next month’s known obligations. Chart lines connect saved checkpoints, not live market prices. Forecasts exclude uncertain income and unexpected bills, so a positive balance does not guarantee safety. The original procedural soundtrack starts only when you turn it on; adjust volume or stop it anytime. It pauses when the tab is hidden.')}</p></section><div class="guide-sections">${sections.map(([title,body],i)=>`<section><h2>${title}</h2><p>${body}</p>${i===1?levelTable(lang):''}${i===8?wagerRulesHTML(lang):''}${i===6?`<div class="guide-callout">${pick('Quy tắc ngắn: sống đủ 12 tháng + trả được nghĩa vụ + đạt điểm mục tiêu = thắng.','Short rule: complete 12 months + meet required payments + reach target score = win.')}</div>`:''}</section>`).join('')}</div><p class="guide-source">${pick('Nguồn tham khảo về Cờ Tỷ Phú:','Monopoly background sources:')} <a href="https://www.museumofplay.org/toys/monopoly/" target="_blank" rel="noopener noreferrer">The Strong National Museum of Play</a> · <a href="https://www.hasbro.com/common/instruct/Monopoly.pdf" target="_blank" rel="noopener noreferrer">Hasbro</a></p>`;
}
function levelTable(lang){const vi=lang==='vi';return `<div class="guide-table-wrap"><table class="guide-table"><thead><tr>${(vi?['Cấp','Vốn ban đầu','Lương / Sinh hoạt','Mốc tài sản','Thắng / Cam kết']:['Level','Starting funds','Salary / Living costs','Wealth benchmark','Target / Commitment']).map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${Object.values(LEVELS).map(l=>`<tr><th>${l[lang][0]}</th><td>${money(l.cash)} + ${money(l.reserve)} ${vi?'dự phòng':'reserve'}</td><td>${money(l.salary)} / ${money(l.living)}</td><td>${money(wealthBenchmark({difficulty:l.id,balanceVersion:22}))}</td><td>≥${l.target}/100 · ${l.bond} HUB</td></tr><tr><td colspan="5">${l[lang][2]}</td></tr>`).join('')}</tbody></table></div>`;}
